//! 🧪️ Original typed native wake payload allocations remain behind their admitted lease and shared fronts.
use super::*;
static WAKES:std::sync::atomic::AtomicUsize=std::sync::atomic::AtomicUsize::new(0);
#[derive(semio_framework_value::RetireOwned)]
struct WakePayload{original:Vec<u8>}
impl std::task::Wake for WakePayload{fn wake(self:Arc<Self>){WAKES.fetch_add(1,Ordering::Relaxed);}fn wake_by_ref(self:&Arc<Self>){WAKES.fetch_add(1,Ordering::Relaxed);}}
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn worker_original_typed_wake_retirement_preserves_native_lease_aliases_and_physical_payload(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};
 for bytes in [0,65536]{for aliases in [0,1,3]{let((mut original,pointer,arc_pointer),birth)=observe(||{let mut payload=Vec::with_capacity(bytes);payload.resize(bytes,7u8);let pointer=payload.as_ptr();let original=Arc::new(WakePayload{original:payload});let arc_pointer=Arc::as_ptr(&original);(Some(original),pointer,arc_pointer)});let mut original_aliases:[Option<Arc<WakePayload>>;3]=std::array::from_fn(|index|(index<aliases).then(||Arc::clone(original.as_ref().unwrap())));let frame_bytes=size_of::<OriginalWorkerWake<WakePayload>>();let copy_bytes=frame_bytes+size_of::<Option<Arc<WakePayload>>>();
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:copy_bytes-1,..grant},RetainedCloneGrant{maximum_capacity_bytes:frame_bytes-1,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(admitted,heap)=observe(||admit_original_worker_wake(&mut original,denied).unwrap());assert!(admitted.is_none());assert_eq!(heap,(0,0));assert_eq!(Arc::as_ptr(original.as_ref().unwrap()),arc_pointer);assert_eq!(original.as_ref().unwrap().original.as_ptr(),pointer);}
 let((mut owner,receipt),heap)=observe(||admit_original_worker_wake(&mut original,grant).unwrap().unwrap());assert!(original.is_none());assert!(receipt.fits(grant));assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),heap);let mut born=birth.0+heap.0;let mut released=birth.1+heap.1;let(_,heap)=observe(||owner.wake_by_ref());assert_eq!(heap,(0,0));let mut turns=0;
 while !owner.terminal_is_empty(){turns+=1;assert!(turns<8192);let(demand,heap)=observe(||owner.retirement_demands(grant.maximum_copy_bytes).unwrap());assert_eq!(heap,(0,0));for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant})].into_iter().flatten(){let(step,heap)=observe(||owner.close_step(denied).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}
 if turns==2&&aliases>0{let(step,heap)=observe(||owner.close_step(grant).unwrap());assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));for alias in original_aliases.iter().flatten(){assert_eq!(Arc::as_ptr(alias),arc_pointer);assert_eq!(alias.original.as_ptr(),pointer);}let(_,heap)=observe(||for alias in &mut original_aliases{drop(alias.take());});assert_eq!(heap,(0,0));}
 let(step,heap)=observe(||owner.close_step(grant).unwrap());assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);born+=heap.0;released+=heap.1;}
 let frame=owner.frame_release_bytes();assert_eq!(frame,frame_bytes);assert!(frame<=grant.maximum_release_bytes);let(_,heap)=observe(||drop(owner));assert_eq!(heap,(0,frame));released+=heap.1;assert_eq!(born,released);eprintln!("[DEBUG] actual original typed Worker wake payload={bytes} aliases={aliases} original payload/Arc addresses retained zero/below4096 Wakerlease physical0 originalArc then originalpayload then terminalcursor and frame funded turns={turns} physical={released} terminalbodyDrop0");}}
}

struct SessionWakeJob;
impl InteractiveJob for SessionWakeJob{fn step<'a>(&'a mut self,cx:&mut StepContext<'_>)->Result<Option<JobOutcomeBorrow<'a>>,ValueError>{JobOutcomeBorrow::admit_yield(cx)}fn borrow_outcome<'a>(&'a self,descriptor:&'a JobOutcomeDescriptor)->Result<JobOutcomeView<'a>,ValueError>{match descriptor.kind(){JobOutcomeKind::Yield=>descriptor.yielded(),JobOutcomeKind::Cancelled=>descriptor.cancelled(),_=>Err(ValueError::literal(ValueRefusalKind::InvariantViolated,"fixture requires original yielded descriptor"))}}fn begin_close(&mut self){}fn close_step(&mut self,_:RetainedCloneGrant)->InteractiveJobCloseStep{InteractiveJobCloseStep::Complete{progress:Default::default()}}fn terminal_is_empty(&self)->bool{true}}
#[test]
fn worker_original_typed_wake_live_session_keeps_custody_through_wake_and_all_paid_frontiers(){
 let _admission=worker_session_slots_shared();let(_,shared_trace)=observe(||record_operation_started(OperationId(99319),Generation(13)));eprintln!("[DEBUG] explicit shared Trace startup before live typed wake session born={} released={}",shared_trace.0,shared_trace.1);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};
 let(mut session,birth)=observe(||admit_original_fixture_owner!(WorkerJobSession,SessionWakeJob,BatchJobParams{operation:OperationId(99320),generation:Generation(13),cancel:CancelToken::root_now(),config:BatchDriveConfig{retained:grant,site:"test.original-typed-wake-session",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:1000},now_us:default_now_us}).unwrap_or_else(|_|panic!("original typed wake session")));let((mut original,pointer),payload_birth)=observe(||{let payload=vec![7u8;65536];let pointer=payload.as_ptr();(Some(Arc::new(WakePayload{original:payload})),pointer)});let((owner,receipt),frame_birth)=observe(||admit_original_worker_wake(&mut original,grant).unwrap().unwrap());assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),frame_birth);let mut owner=Some(owner);let original_frame=owner.as_ref().unwrap().as_ref()as*const dyn RetainedWorkerWake;
 for denied in [RetainedCloneGrant{maximum_items:0,..grant},RetainedCloneGrant{maximum_copy_bytes:0,..grant},RetainedCloneGrant{maximum_depth:0,..grant}]{let(receipt,heap)=observe(||session.register_retained_wake(&mut owner,denied).unwrap());assert!(receipt.is_none());assert_eq!(heap,(0,0));assert!(std::ptr::eq(owner.as_ref().unwrap().as_ref()as*const dyn RetainedWorkerWake,original_frame));}
 let(receipt,heap)=observe(||session.register_retained_wake(&mut owner,grant).unwrap().unwrap());assert!(receipt.fits(grant));assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),heap);assert!(owner.is_none());let(_,heap)=observe(||session.begin_close());assert_eq!(heap,(0,0));assert_eq!(unsafe{std::slice::from_raw_parts(pointer,65536)},vec![7u8;65536].as_slice());let mut born=birth.0+payload_birth.0+frame_birth.0;let mut released=birth.1+payload_birth.1+frame_birth.1;let mut turns=0;
 while !session.terminal_is_empty(){turns+=1;assert!(turns<8192);let(demand,heap)=observe(||session.retirement_demands(grant.maximum_copy_bytes).unwrap());assert_eq!(heap,(0,0));for denied in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant})].into_iter().flatten(){let(step,heap)=observe(||session.close_step(denied));assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}
 let(step,heap)=observe(||session.close_step(grant));assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);born+=heap.0;released+=heap.1;}
 assert_eq!(born,released);let(_,heap)=observe(||drop(session));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original typed wake live Worker session original payload65536 original frame retained registration zero/below4096 real wake borrowed physical0 all child/full original receipts per-turn exact heap turns={turns} physical={released} terminalDrop0 semantic job/outcome/scheduler transfer excluded");
}

#[test]
fn worker_original_typed_wake_parked_session_keeps_original_arc_and_separate_node_release(){
 let _admission=worker_session_slots_exclusive();let(_,shared_trace)=observe(||record_operation_started(OperationId(99419),Generation(14)));eprintln!("[DEBUG] explicit shared Trace startup before parked typed wake session born={} released={}",shared_trace.0,shared_trace.1);let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_capacity_bytes:65536,maximum_release_bytes:262144,maximum_depth:64};let mut prior_turns=0;while worker_job_retirements_are_parked(){prior_turns+=1;assert!(prior_turns<8192);let(step,heap)=observe(||pump_worker_job_retirements(1,grant));assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);}let(mut session,birth)=observe(||admit_original_fixture_owner!(WorkerJobSession,SessionWakeJob,BatchJobParams{operation:OperationId(99420),generation:Generation(14),cancel:CancelToken::root_now(),config:BatchDriveConfig{retained:grant,site:"test.original-parked-typed-wake",stage:InteractiveStage::InteractiveStep,fuel_per_step:1,step_budget_us:1000},now_us:default_now_us}).unwrap_or_else(|_|panic!("original parked wake session")));let arc_pointer=Arc::as_ptr(&session.inner);let slot=unsafe{(&*session.retirement.get()).as_ref().unwrap().header.slot};let(mut original,payload_birth)=observe(||Some(Arc::new(WakePayload{original:vec![7u8;65536]})));let((owner,receipt),frame_birth)=observe(||admit_original_worker_wake(&mut original,grant).unwrap().unwrap());assert_eq!((receipt.retained_capacity_bytes,receipt.released_bytes),frame_birth);let mut owner=Some(owner);session.register_retained_wake(&mut owner,grant).unwrap().unwrap();let(_,heap)=observe(||drop(session));assert_eq!(heap,(0,0));let pointer=WORKER_JOB_RETIREMENT_SLOTS[slot].load(Ordering::Acquire);assert!(!pointer.is_null());let parked=unsafe{&*pointer.cast::<WorkerJobRetirementNode<SessionWakeJob>>()};assert_eq!(Arc::as_ptr(parked.inner.as_ref().unwrap()),arc_pointer);let mut born=birth.0+payload_birth.0+frame_birth.0;let mut released=birth.1+payload_birth.1+frame_birth.1;let mut turns=0;let mut saw_arc=false;let mut saw_node=false;
 while worker_job_retirements_are_parked(){turns+=1;assert!(turns<8192);let(phase,heap)=observe(||worker_job_retirement_phase(1).unwrap());assert_eq!(heap,(0,0));saw_arc|=phase==WorkerJobClosePhase::SessionArc;saw_node|=phase==WorkerJobClosePhase::RetirementSlot;let(step,heap)=observe(||pump_worker_job_retirements(1,RetainedCloneGrant{maximum_items:0,..grant}));assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));assert_eq!(WORKER_JOB_RETIREMENT_SLOTS[slot].load(Ordering::Acquire),pointer);let(step,heap)=observe(||pump_worker_job_retirements(1,grant));assert!(step.progress().fits(grant));assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);born+=heap.0;released+=heap.1;}
 assert!(saw_arc&&saw_node);assert_eq!(born,released);assert!(WORKER_JOB_RETIREMENT_SLOTS[slot].load(Ordering::Acquire).is_null());eprintln!("[DEBUG] actual original typed wake parked Worker Drop retains original Arc and node pointer physical0 child65536payload then originalArc and originalnode separate paid turns={turns} physical={released} copy4096 semantic Drop/session handoff excluded");
}

